104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
107	        List<String> missingFields = new ArrayList<>();
108	        if (isBlank(ownerFieldsDto.getFirstName())) {
109	            missingFields.add("firstName");
110	        }
111	        if (isBlank(ownerFieldsDto.getLastName())) {
112	            missingFields.add("lastName");
113	        }
114	        if (isBlank(ownerFieldsDto.getAddress())) {
115	            missingFields.add("address");
116	        }
117	        if (isBlank(ownerFieldsDto.getCity())) {
118	            missingFields.add("city");
119	        }
120	        if (isBlank(ownerFieldsDto.getTelephone())) {
121	            missingFields.add("telephone");
122	        }
123	        if (!missingFields.isEmpty()) {
124	            throw new InvalidOwnerFieldsException(missingFields);
125	        }
126	        // Normalize the telephone into E.164 form; a number that cannot form a valid
127	        // E.164 value is rejected with a 400.
128	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
129	        // Email is optional; when present it must be a syntactically valid address and is
130	        // stored lower-cased. An invalid address is rejected with a 400.
131	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
132	        // Reject the request if the E.164 telephone is already used by any other owner.
133	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
134	            .map(Owner::getTelephone)
135	            .filter(existing -> existing != null)
136	            .anyMatch(normalizedTelephone::equals);
137	        if (telephoneInUse) {
138	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
139	        }
140	        HttpHeaders headers = new HttpHeaders();
141	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
142	        owner.setTelephone(normalizedTelephone);
143	        owner.setEmail(normalizedEmail);
144	        // When no registration date is supplied, default it to the server's current date.
145	        if (owner.getRegistrationDate() == null) {
146	            owner.setRegistrationDate(LocalDate.now());
147	        }
148	        this.clinicService.saveOwner(owner);
149	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
150	        headers.setLocation(UriComponentsBuilder.newInstance()
151	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
152	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
153	    }
