237	    @Override
238	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
239	        Owner owner = this.clinicService.findOwnerById(ownerId);
240	        if (owner != null) {
241	            Pet pet = owner.getPet(petId);
242	            if (pet != null) {
243	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
244	            }
245	        }
246	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
247	    }
248	
249	    private static boolean isBlank(String value) {
250	        return value == null || value.trim().isEmpty();
251	    }
252	
253	    /**
254	     * Convert a raw telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
255	     * {@code '+'} with its country code is preserved; otherwise the Australian country code
256	     * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national digits.
257	     * The result must be a {@code '+'} followed by 8 to 15 digits, otherwise an
258	     * {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a 400.
259	     */
260	    private static String toE164(String raw) {
261	        String cleaned = raw.trim().replaceAll("[\\s()\\-]", "");
262	        boolean hasCountryCode = cleaned.startsWith("+");
263	        String digits = hasCountryCode ? cleaned.substring(1) : cleaned;
264	        if (!digits.matches("\\d+")) {
265	            throw new InvalidOwnerFieldsException(List.of("telephone"));
266	        }
267	        if (!hasCountryCode) {
268	            if (digits.startsWith("0")) {
269	                digits = digits.substring(1);
270	            }
271	            digits = "61" + digits;
272	        }
273	        if (digits.length() < 8 || digits.length() > 15) {
274	            throw new InvalidOwnerFieldsException(List.of("telephone"));
275	        }
276	        return "+" + digits;
277	    }
278	
279	    /**
280	     * Pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
281	     * and a domain with at least one dot-separated label, none of which contain whitespace or
282	     * a second {@code @}. This is deliberately permissive but rejects obviously malformed input.
283	     */
284	    private static final Pattern EMAIL_PATTERN =
285	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
286	
287	    /**
288	     * Validate and normalize an optional owner email. Returns {@code null} when no email was
289	     * supplied (the field is optional). When supplied it must be a syntactically valid address,
290	     * otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a
291	     * 400. A valid address is returned lower-cased.
292	     */
293	    private static String normalizeEmail(String email) {
294	        if (email == null || email.isEmpty()) {
295	            return null;
296	        }
297	        String trimmed = email.trim();
298	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
299	            throw new InvalidOwnerFieldsException(List.of("email"));
300	        }
301	        return trimmed.toLowerCase();
302	    }
303	}
